public class AIBenchmarkJobFactory(string resourceName = null, Action<Humidifier.SageMaker.AIBenchmarkJob> factoryAction = null) : ResourceFactory<Humidifier.SageMaker.AIBenchmarkJob>(resourceName)
{

    internal InnerAIBenchmarkJobAIBenchmarkOutputConfigFactory OutputConfigFactory { get; set; }

    internal InnerAIBenchmarkJobAIBenchmarkNetworkConfigFactory NetworkConfigFactory { get; set; }

    internal InnerAIBenchmarkJobAIBenchmarkTargetFactory BenchmarkTargetFactory { get; set; }

    protected override Humidifier.SageMaker.AIBenchmarkJob Create()
    {
        var aIBenchmarkJobResult = CreateAIBenchmarkJob();
        factoryAction?.Invoke(aIBenchmarkJobResult);

        return aIBenchmarkJobResult;
    }

    private Humidifier.SageMaker.AIBenchmarkJob CreateAIBenchmarkJob()
    {
        var aIBenchmarkJobResult = new Humidifier.SageMaker.AIBenchmarkJob
        {
            GivenName = InputResourceName,
        };

        return aIBenchmarkJobResult;
    }
    public override void CreateChildren(Humidifier.SageMaker.AIBenchmarkJob result)
    {
        base.CreateChildren(result);

        result.OutputConfig ??= OutputConfigFactory?.Build();
        result.NetworkConfig ??= NetworkConfigFactory?.Build();
        result.BenchmarkTarget ??= BenchmarkTargetFactory?.Build();
    }

} // End Of Class

